        C.append(c)
        idx += 2
    min_cost = float('inf')
    # Check single strings
    for i in range(N):
        if is_palindrome(S[i]):
            if C[i] < min_cost:
                min_cost = C[i]
    # Check pairs
    for i in range(N):
        for j in range(N):
            s1 = S[i]
            s2 = S[j]
            if is_palindrome(s1 + s2):
                cost = C[i] + C[j]
                if cost < min_cost:
