        # Merge new_dp into dp
        for s in new_dp:
            if s not in dp or new_dp[s] < dp[s]:
                dp[s] = new_dp[s]

    # Find the minimal cost palindrome
    min_cost = float('inf')
    for s in dp:
        if is_pal(s):
            if dp[s] < min_cost:
                min_cost = dp[s]

