            combined1 = s1 + s2
            if is_palindrome(combined1):
                total = c1 + c2
                if total < min_cost:
                    min_cost = total
            combined2 = s2 + s1
            if is_palindrome(combined2):
                total = c1 + c2
                if total < min_cost:
                    min_cost = total

    if min_cost == float('inf'):
        print(-1)
