def kosaraju(n, adj):
    visited = [False] * (n + 1)
    order = []

    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in adj[node]:
                if not visited[v]:
                    stack.append((v, False))

    for u in range(1, n+1):
        if not visited[u]:
            dfs(u)

    # Reverse graph
    rev_adj = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for v in adj[u]:
            rev_adj[v].append(u)

    visited = [False] * (n+1)
    scc = []
    def reverse_dfs(u, component):
        stack = [u]
        visited[u] = True
        component.append(u)
        while stack:
            node = stack.pop()
            for v in rev_adj[node]:
                if not visited[v]:
                    visited[v] = True
                    component.append(v)
                    stack.append(v)
    for u in reversed(order):
        if not visited[u]:
            component = []
            reverse_dfs(u, component)
            scc.append(component)
    return scc

