from functools import lru_cache

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    K = int(input[idx])
    idx += 1
    A = list(map(int, input[idx:idx+N]))

    max_bit = 40  # since K can be up to 1e12, which is 40 bits
    count_ones = [0] * (max_bit + 1)
    for a in A:
        for bit in range(max_bit + 1):
            if a & (1 << bit):
                count_ones[bit] += 1

    @lru_cache(maxsize=None)
    def dfs(bit, is_tight):
        if bit < 0:
            return 0
        max_bit_val = (K >> bit) & 1 if is_tight else 1
        res = 0
        for possible_bit in [0, 1]:
            if possible_bit > max_bit_val:
                continue
            # calculate contribution
            if possible_bit == 1:
                contrib = (N - count_ones[bit]) * (1 << bit)
            else:
                contrib = count_ones[bit] * (1 << bit)
            new_is_tight = is_tight and (possible_bit == max_bit_val)
            res = max(res, contrib + dfs(bit - 1, new_is_tight))
        return res

    print(dfs(max_bit, True))

