import sys

def main():
    N = int(sys.stdin.readline())
    A = list(map(int, sys.stdin.readline().split()))
    base_xor = 0
    for i in range(2, N):
        base_xor ^= A[i]
    S = A[0] + A[1]
    K = base_xor
    T = S - K
    if T < 0 or T % 2 != 0:
        print(-1)
        return
    M = T // 2
    if (K & M) != 0:
        print(-1)
        return
    limit = A[0] - M
    if M > A[0]:
        print(-1)
        return
    target_max = 0
    for bit in reversed(range(60)):
        if (K >> bit) & 1:
            candidate = target_max | (1 << bit)
            if candidate <= limit:
                target_max = candidate
    a = M + target_max
    if 1 <= a <= A[0]:
        print(A[0] - a)
    else:
        print(-1)

