import sys
from collections import defaultdict, deque

def main():
    N = int(sys.stdin.readline())
    A = []
    for _ in range(N):
        A.append(list(map(int, sys.stdin.readline().split())))

    matches = set()
    for u in range(1, N+1):
        for v in A[u-1]:
            match = (min(u, v), max(u, v))
            matches.add(match)

    graph = defaultdict(list)
    in_degree = defaultdict(int)

    for u in range(1, N+1):
        opponents = A[u-1]
        for i in range(len(opponents) - 1):
            a = opponents[i]
            b = opponents[i+1]
            match1 = (min(u, a), max(u, a))
            match2 = (min(u, b), max(u, b))
            graph[match1].append(match2)
            in_degree[match2] += 1

    queue = deque()
    for match in matches:
        if in_degree[match] == 0:
            queue.append(match)

    topological_order = []
    count = 0
    while queue:
        node = queue.popleft()
        topological_order.append(node)
        count += 1
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if count != len(matches):
        print(-1)
        return

    distance = defaultdict(int)
    for node in topological_order:
        for neighbor in graph[node]:
            if distance[neighbor] < distance[node] + 1:
                distance[neighbor] = distance[node] + 1

    max_distance = max(distance.values()) if distance else 0
    print(max_distance + 1)

