    for i in range(1, N+1):
        for j in range(i+1, N+1):
            matches.append( (i,j) )
            match_id[ (i,j) ] = len(matches) - 1

    # Build adjacency list
    adj = [[] for _ in range(len(matches))]
    for idx, (i,j) in enumerate(matches):
        pos_i = pos_dict[i][j]
        pos_j = pos_dict[j][i]
        prev_matches = set()
        # Process i's list
        for k in range(pos_i):
            opponent = A[i-1][k]
            if i < opponent:
                prev_match = (i, opponent)
            else:
                prev_match = (opponent, i)
            prev_matches.add(prev_match)
        # Process j's list
        for k in range(pos_j):
            opponent = A[j-1][k]
            if j < opponent:
                prev_match = (j, opponent)
            else:
                prev_match = (opponent, j)
            prev_matches.add(prev_match)
        # Add edges
        for prev_match in prev_matches:
            prev_idx = match_id[prev_match]
            adj[prev_idx].append(idx)

    # Check for cycles using Kahn's algorithm
    in_degree = [0] * len(matches)
    for u in range(len(matches)):
        for v in adj[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(len(matches)):
        if in_degree[i] == 0:
            queue.append(i)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(top_order) != len(matches):
        print(-1)
        return

    # Compute longest path
