from collections import defaultdict, deque

def main():
    n = int(sys.stdin.readline())
    opponents = []
    for _ in range(n):
        opponents.append(list(map(int, sys.stdin.readline().split())))

    matches = set()
    for i in range(n):
        player = i + 1
        for j in opponents[i]:
            u = min(player, j)
            v = max(player, j)
            matches.add((u, v))

    adj = defaultdict(set)
    for i in range(n):
        player = i + 1
        op_list = opponents[i]
        for k in range(len(op_list) - 1):
            current_op = op_list[k]
            next_op = op_list[k+1]
            current_match = (min(player, current_op), max(player, current_op))
            next_match = (min(player, next_op), max(player, next_op))
            if next_match not in adj[current_match]:
                adj[current_match].add(next_match)

    indegree = defaultdict(int)
    for u in matches:
        for v in adj[u]:
            indegree[v] += 1

    queue = deque()
    for u in matches:
        if indegree[u] == 0:
            queue.append(u)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    if len(top_order) != len(matches):
        print(-1)
        return

    distance = {node: 0 for node in matches}
    for u in top_order:
        for v in adj[u]:
            if distance[v] < distance[u] + 1:
                distance[v] = distance[u] + 1

    max_dist = max(distance.values())
    print(max_dist + 1)

