    min_cuts = float('inf')

    for mask in range(1 << (H-1)):
        split_points = []
        for i in range(H-1):
            if (mask >> i) & 1:
                split_points.append(i)
        groups = []
        start = 0
        for sp in split_points:
            groups.append((start, sp))
            start = sp + 1
        groups.append((start, H-1))

        group_col_sums = []
        for (start_row, end_row) in groups:
            col_sums = []
            for j in range(W):
                total = 0
                for i in range(start_row, end_row + 1):
                    total += grid[i][j]
                col_sums.append(total)
            group_col_sums.append(col_sums)

        current_sums = [0] * len(groups)
        vertical_cuts = 0
        for j in range(W):
            for g in range(len(groups)):
                current_sums[g] += group_col_sums[g][j]
            overflow = False
            for g in range(len(groups)):
                if current_sums[g] > K:
                    overflow = True
                    break
            if overflow:
                vertical_cuts += 1
                for g in range(len(groups)):
                    current_sums[g] = group_col_sums[g][j]

        total_cuts = (len(groups) - 1) + vertical_cuts
        if total_cuts < min_cuts:
            min_cuts = total_cuts

    print(min_cuts)

