        ptr += N

    group0 = []
    group1 = []
    group2 = []
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            mod = (i + j) % 3
            color = c_grid[i - 1][j - 1]
            if mod == 0:
                group0.append(color)
            elif mod == 1:
                group1.append(color)
            else:
                group2.append(color)

    cost0 = [0] * (C + 1)
    for t in range(1, C + 1):
        total = 0
        for c in group0:
            total += D[c][t]
        cost0[t] = total

    cost1 = [0] * (C + 1)
    for t in range(1, C + 1):
        total = 0
        for c in group1:
            total += D[c][t]
        cost1[t] = total

