from collections import deque

def main():
    N, X, Y = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(N+1)]
    for i in range(1, N):
        adj[i].append(i+1)
        adj[i+1].append(i)
    adj[X].append(Y)
    adj[Y].append(X)

    count = [0] * (N)  # indexes 0 to N-1

    for u in range(1, N+1):
        dist = [-1] * (N+1)
        q = deque()
        q.append(u)
        dist[u] = 0
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[current] + 1
                    q.append(neighbor)
        for v in range(u+1, N+1):
            d = dist[v]
            if d <= N-1:
                count[d] += 1

    for k in range(1, N):
        print(count[k])

