                    if pattern[pos_prev - 1] == 1:
                        new_pos = pos_prev + 1
                temp_dp[new_pos] = (temp_dp[new_pos] + prev_dp[pos_prev]) % MOD
            # Add temp_dp to curr_dp
            for pos in range(1, W + 1):
                curr_dp[pos] = (curr_dp[pos] + temp_dp[pos]) % MOD
        prev_dp = curr_dp

    print(prev_dp[K] % MOD)

