from collections import deque

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    road_positions = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == '.']

    max_dist = 0

    for (si, sj) in road_positions:
        visited = [[-1 for _ in range(W)] for _ in range(H)]
        q = deque()
        visited[si][sj] = 0
        q.append((si, sj))
        current_max = 0

        while q:
            x, y = q.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < H and 0 <= ny < W:
                    if grid[nx][ny] == '.' and visited[nx][ny] == -1:
                        visited[nx][ny] = visited[x][y] + 1
                        current_max = max(current_max, visited[nx][ny])
                        q.append((nx, ny))

        max_dist = max(max_dist, current_max)

    print(max_dist)

