            j = i + 1
            while j < N and p[j] == j + 1:
                j += 1
            if j < N:
                p[i], p[j] = p[j], p[i]
                total_swaps += j - i
                i += 1
            else:
                if i + 1 < N:
                    p[i], p[i + 1] = p[i + 1], p[i]
                    total_swaps += 1
                    i += 1
                else:
                    if i - 1 >= 0:
                        p[i], p[i - 1] = p[i - 1], p[i]
                        total_swaps += 1
                        i += 1
        else:
            i += 1
    print(total_swaps)

