def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    W = int(input[idx])
    idx += 1
    items = []
    w0 = None
    for _ in range(N):
        w = int(input[idx])
        idx += 1
        v = int(input[idx])
        idx += 1
        items.append((w, v))
    w0 = items[0][0]
    # Group items into 4 groups based on weight
    groups = [[] for _ in range(4)]
    for w, v in items:
        group = w - w0
        if 0 <= group <= 3:
            groups[group].append(v)
    # Sort each group in descending order of value
    for g in range(4):
        groups[g].sort(reverse=True)
    # Compute prefix sums for each group
    prefix = [[0] for _ in range(4)]
    for g in range(4):
        s = 0
        for val in groups[g]:
            s += val
            prefix[g].append(s)
    max_total = 0
    for k in range(0, N + 1):
        S = W - w0 * k
        if S < 0:
            continue
        current_max = 0
        # Determine the maximum m (number of items from groups 1-3)
        max_m = min(k, len(groups[1]) + len(groups[2]) + len(groups[3]))
        for m in range(0, max_m + 1):
            # Iterate over possible y (items from group1)
            max_y = min(len(groups[1]), m)
            for y in range(0, max_y + 1):
                # Iterate over possible z (items from group2)
                max_z = min(len(groups[2]), m - y)
                for z in range(0, max_z + 1):
                    t = m - y - z
                    if t < 0 or t > len(groups[3]):
                        continue
                    # Calculate the cost
                    cost = y + 2 * z + 3 * t
                    if cost > S:
