        count_left = s.count('(')
        count_right = s.count(')')
        total_balance = count_left - count_right

        balance = 0
        min_b = 0
        max_b = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            min_b = min(min_b, balance)
            max_b = max(max_b, balance)

        if total_balance > 0:
            positive.append((min_b, total_balance))
        elif total_balance < 0:
            negative.append((max_b, min_b, total_balance))
        else:
            zero.append((min_b, max_b))

    positive.sort(key=lambda x: (-x[0], x[1]))
    negative.sort(key=lambda x: (-x[0], x[1], x[2]))
    zero.sort(key=lambda x: (-x[0], x[1]))

    current_balance = 0

    for min_b, total_balance in positive:
        if current_balance + min_b < 0:
            print("No")
            return
        current_balance += total_balance

    for min_b, max_b in zero:
        if current_balance + min_b < 0:
            print("No")
            return

    for max_b, min_b, total_balance in negative:
        if current_balance + min_b < 0:
            print("No")
            return
        current_balance += total_balance

    print("Yes")

