def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:N+1]))

    max_score = -10**18

    def simulate(A, B, N, s):
        current = 0
        visited = {0}
        score = 0
        steps = 0
        while True:
            if steps % 2 == 0:
                next_pos = current + A
            else:
                next_pos = current - B
            steps += 1
            if next_pos < 0 or next_pos >= N:
                return -10**18
            if next_pos in visited:
                return -10**18
            if next_pos == N-1:
                return score
            visited.add(next_pos)
            score += s[next_pos]
            current = next_pos

    # Handle odd steps
    for k in range(0, N):
        # Odd steps: m = 2k + 1
        if k == 0:
            A = N - 1
            # B can be any positive integer, but simulate with B=1
            score = simulate(A, 1, N, s)
            if score > max_score:
                max_score = score
        else:
            R = (N - 1) % k
            t = 0
            while True:
                A = R + t * k
                if A > N - 1:
                    break
                numerator = (k + 1) * A - (N - 1)
                if numerator % k != 0:
                    t += 1
                    continue
                B = numerator // k
                if B <= 0:
                    t += 1
                    continue
                score = simulate(A, B, N, s)
                if score > max_score:
                    max_score = score
                t += 1

    # Handle even steps
    for k in range(1, N):
        # Even steps: m = 2k
        if k - 1 == 0:
            continue  # already handled in odd steps for k=0
        R_even = (N - 1) % (k - 1)
        t_even = 0
        while True:
            A = R_even + t_even * (k - 1)
            if A > N - 1:
                break
            numerator_even = k * A - (N - 1)
            if numerator_even % (k - 1) != 0:
                t_even += 1
                continue
            B_even = numerator_even // (k - 1)
            if B_even <= 0:
                t_even += 1
                continue
            score = simulate(A, B_even, N, s)
            if score > max_score:
                max_score = score
            t_even += 1

    print(max_score)

