    for i in range(2, int(max_a**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_a + 1, i):
                if spf[j] == j:
                    spf[j] = i

    prime_count = {}
    for num in A:
        if num == 1:
            continue
        x = num
        primes = set()
        while x != 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        for p in primes:
            if p in prime_count:
                prime_count[p] += 1
            else:
                prime_count[p] = 1

    pairwise = True
    for count in prime_count.values():
        if count >= 2:
            pairwise = False
            break

    if pairwise:
        print("pairwise coprime")
        return

    current_gcd = A[0]
    for num in A[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break

    if current_gcd == 1:
        print("setwise coprime")
    else:
        print("not coprime")

