        x_coords = []
        y_coords = []
        for x, y, d in points:
            if d == 'R':
                xc = x + t
            elif d == 'L':
                xc = x - t
            else:
                xc = x
            x_coords.append(xc)
            if d == 'U':
                yc = y + t
            elif d == 'D':
                yc = y - t
            else:
                yc = y
            y_coords.append(yc)
        max_x = max(x_coords)
        min_x = min(x_coords)
        max_y = max(y_coords)
        min_y = min(y_coords)
        return (max_x - min_x) * (max_y - min_y)

    def compute_x_spread(t):
        x_coords = []
        for x, y, d in points:
            if d == 'R':
                xc = x + t
            elif d == 'L':
                xc = x - t
            else:
                xc = x
            x_coords.append(xc)
        return max(x_coords) - min(x_coords)

    def compute_y_spread(t):
        y_coords = []
        for x, y, d in points:
            if d == 'U':
                yc = y + t
            elif d == 'D':
                yc = y - t
            else:
                yc = y
            y_coords.append(yc)
        return max(y_coords) - min(y_coords)

    def find_min_t(f, low, high, eps=1e-8):
        for _ in range(100):
            mid1 = low + (high - low)/3
            mid2 = high - (high - low)/3
            f1 = f(mid1)
            f2 = f(mid2)
            if f1 < f2:
                high = mid2
            else:
                low = mid1
        return (low + high)/2

    t_min_x = find_min_t(compute_x_spread, 0.0, 1e14)
    t_min_y = find_min_t(compute_y_spread, 0.0, 1e14)

    candidates = [0.0, t_min_x, t_min_y]

    min_val = float('inf')
    for t in candidates:
        val = compute_product(t)
        if val < min_val:
            min_val = val

