def count_subsets(X, mask):
    if mask == 0:
        return 1 if X >= 0 else 0
    highest_bit = mask.bit_length() - 1
    x_highest_bit = X.bit_length() - 1
    if x_highest_bit < highest_bit:
        return count_subsets(X, mask & ~(1 << highest_bit))
    elif x_highest_bit > highest_bit:
        return (1 << (mask.bit_count())) % MOD
    else:
        mask_without = mask & ~(1 << highest_bit)
        return (count_subsets(X & ~(1 << highest_bit), mask_without) + count_subsets(X, mask_without)) % MOD

