def main():
    S = sys.stdin.readline().strip()
    Q = int(sys.stdin.readline())
    dq = deque(S)
    reversed_flag = False
    for _ in range(Q):
        parts = sys.stdin.readline().split()
        if parts[0] == '1':
            reversed_flag = not reversed_flag
        else:
            F_i = int(parts[1])
            C_i = parts[2]
            if reversed_flag:
                if F_i == 1:
                    dq.append(C_i)
                else:
                    dq.appendleft(C_i)
            else:
                if F_i == 1:
                    dq.appendleft(C_i)
                else:
                    dq.append(C_i)
    if reversed_flag:
        result = ''.join(reversed(dq))
    else:
        result = ''.join(dq)
    print(result)

