    import sys
    input = sys.stdin.read
    data = input().split()

    H = int(data[0])
    W = int(data[1])
    grid = data[2:2+H]

    left = [[0]*W for _ in range(H)]
    right = [[0]*W for _ in range(H)]
    up = [[0]*W for _ in range(H)]
    down = [[0]*W for _ in range(H)]

    # Compute left and right
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                left[i][j] = 0
            else:
                if j == 0:
                    left[i][j] = 1
                else:
                    left[i][j] = left[i][j-1] + 1
        for j in range(W-1, -1, -1):
            if grid[i][j] == '#':
                right[i][j] = 0
            else:
                if j == W-1:
                    right[i][j] = 1
                else:
                    right[i][j] = right[i][j+1] + 1

    # Compute up and down
    for j in range(W):
        for i in range(H):
            if grid[i][j] == '#':
                up[i][j] = 0
            else:
                if i == 0:
                    up[i][j] = 1
                else:
                    up[i][j] = up[i-1][j] + 1
        for i in reversed(range(H)):
            if grid[i][j] == '#':
                down[i][j] = 0
            else:
                if i == H-1:
                    down[i][j] = 1
                else:
                    down[i][j] = down[i+1][j] + 1

    max_val = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                total = left[i][j] + right[i][j] + up[i][j] + down[i][j] - 3
                if total > max_val:
                    max_val = total
    print(max_val)

