from collections import defaultdict

MOD = 10**9 + 7

def normalize(a, b):
    if a == 0 and b == 0:
        return (0, 0)
    g = math.gcd(abs(a), abs(b))
    a //= g
    b //= g
    if a == 0:
        if b < 0:
            b = -b
    else:
        if a < 0:
            a = -a
            b = -b
    return (a, b)

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    dir_count = defaultdict(int)
    zero_count = 0
    for _ in range(N):
        a = int(input[idx])
        b = int(input[idx+1])
        idx += 2
        if a == 0 and b == 0:
            zero_count += 1
        else:
            normalized = normalize(a, b)
            dir_count[normalized] += 1
    processed = set()
    product = 1
    for direction in dir_count:
        if direction not in processed:
            x, y = direction
            perp_x = -y
            perp_y = x
            normalized_perp = normalize(perp_x, perp_y)
            if normalized_perp in dir_count and normalized_perp not in processed:
                count_dir = dir_count[direction]
                count_perp = dir_count[normalized_perp]
                contribution = (pow(2, count_dir, MOD) + pow(2, count_perp, MOD) - 1) % MOD
                product = (product * contribution) % MOD
                processed.add(direction)
