            else:
                count_dir = dir_count[direction]
                contribution = pow(2, count_dir, MOD)
                product = (product * contribution) % MOD
                processed.add(direction)
    total = (product * (zero_count + 1)) % MOD
    total = (total - 1) % MOD
    print(total)

