def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx])
    idx += 1
    S = list(map(int, data[idx:idx+N]))
    idx += N
    T = list(map(int, data[idx:idx+N]))
    idx += N
    U = list(map(int, data[idx:idx+N]))
    idx += N
    V = list(map(int, data[idx:idx+N]))
    idx += N

    a = [[0]*N for _ in range(N)]

    for bit in range(64):
        R0 = [i for i in range(N) if S[i] == 0]
        C0 = [j for j in range(N) if T[j] == 0]
        bit_matrix = [[0]*N for _ in range(N)]

        for i in R0:
            for j in range(N):
                bit_matrix[i][j] = 1
        for j in C0:
            for i in range(N):
                bit_matrix[i][j] = 1

        has_R0 = len(R0) > 0
        has_C0 = len(C0) > 0

        for i in range(N):
            if i not in R0:
                if not has_C0:
                    bit_matrix[i][0] = 1

        for j in range(N):
            if j not in C0:
                if not has_R0:
                    bit_matrix[0][j] = 1

        valid = True
        for i in range(N):
            if S[i] == 0:
                row_and = 1
                for j in range(N):
                    row_and &= bit_matrix[i][j]
                expected = (U[i] >> bit) & 1
                if row_and != expected:
                    valid = False
                    break
            else:
                row_or = 0
                for j in range(N):
                    row_or |= bit_matrix[i][j]
                expected = (U[i] >> bit) & 1
                if row_or != expected:
                    valid = False
                    break
        if not valid:
            print(-1)
            return

        for j in range(N):
            if T[j] == 0:
                col_and = 1
                for i in range(N):
                    col_and &= bit_matrix[i][j]
                expected = (V[j] >> bit) & 1
                if col_and != expected:
                    valid = False
                    break
            else:
                col_or = 0
                for i in range(N):
                    col_or |= bit_matrix[i][j]
                expected = (V[j] >> bit) & 1
                if col_or != expected:
                    valid = False
                    break
        if not valid:
            print(-1)
            return

        for i in range(N):
            for j in range(N):
                a[i][j] |= (bit_matrix[i][j] << bit)

    for row in a:
        print(' '.join(map(str, row)))

